+function showSuccessMessage() {
+    successMessage.setAttribute('aria-hidden', 'false');
+    successMessage.textContent = 'Thank you! Your message has been sent successfully. We\'ll be in touch soon.';
+    successMessage.focus();
+}
+
+form.addEventListener('submit', (e) => {
+    e.preventDefault();
+
+    if (validateForm()) {
+        showSuccessMessage();
